"""Keep the generated MCP fallback version aligned with the Python contract."""

from __future__ import annotations

import json
from pathlib import Path

from decision import schema
from decision.contract import CONTRACT_VERSION, render_json_schema


MCP_VERSION = Path(__file__).resolve().parents[1] / "mcp" / "src" / "contract-version.ts"
EXPECTED = (
    "// Generated by python -m decision.schema. Do not edit.\n"
    f"export const CURRENT_CONTRACT_VERSION = {json.dumps(CONTRACT_VERSION)};\n"
)


def test_generated_mcp_contract_version_matches_python_contract():
    assert MCP_VERSION.is_file(), "run python -m decision.schema"
    assert MCP_VERSION.read_text(encoding="utf-8") == EXPECTED


def test_schema_generator_checks_mcp_version_without_rewriting(tmp_path, monkeypatch):
    schema_path = tmp_path / "decision-contract.schema.json"
    version_path = tmp_path / "contract-version.ts"
    stale = 'export const CURRENT_CONTRACT_VERSION = "2.16";\n'
    schema_path.write_text(render_json_schema(), encoding="utf-8")
    version_path.write_text(stale, encoding="utf-8")
    monkeypatch.setattr(schema, "SCHEMA_PATH", schema_path)
    monkeypatch.setattr(schema, "MCP_VERSION_PATH", version_path, raising=False)

    assert schema.main(["--check"]) == 1
    assert version_path.read_text(encoding="utf-8") == stale
    version_path.write_text(EXPECTED, encoding="utf-8")
    assert schema.main(["--check"]) == 0
    version_path.unlink()
    assert schema.main(["--check"]) == 1
    assert not version_path.exists()


def test_schema_generator_writes_current_mcp_version(tmp_path, monkeypatch):
    schema_path = tmp_path / "decision-contract.schema.json"
    version_path = tmp_path / "contract-version.ts"
    monkeypatch.setattr(schema, "SCHEMA_PATH", schema_path)
    monkeypatch.setattr(schema, "MCP_VERSION_PATH", version_path, raising=False)

    assert schema.main([]) == 0
    assert version_path.read_text(encoding="utf-8") == EXPECTED
    assert schema_path.read_text(encoding="utf-8") == render_json_schema()
